import { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import Layout from "../components/Layout";
import { getUserFromToken } from "../utils/auth";
import { deleteStudent } from "../utils/api";

function AdminStudentProfile() {
  const [student, setStudent] = useState(null);
  const [loading, setLoading] = useState(true);

  const navigate = useNavigate();
  const { id } = useParams(); // <-- gets :id from the route

  useEffect(() => {
    const token = localStorage.getItem("token");

    if (!token) {
      navigate("/login");
      return;
    }

    const user = getUserFromToken(token);

    if (!user || user.role !== "admin") {
      navigate("/login");
      return;
    }

    const studentId = Number(id);

    const getStudent = async () => {
      try {
        const res = await fetch("/api/studentprofile/all", {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        if (!res.ok) {
          navigate("/admin-dashboard");
          return;
        }

        const students = await res.json();

        const foundStudent = students.find((s) => s.id === studentId);

        if (!foundStudent) {
          navigate("/admin-dashboard");
          return;
        }

        setStudent(foundStudent);
      } catch (err) {
        console.error(err);
        navigate("/admin-dashboard");
      } finally {
        setLoading(false);
      }
    };

    getStudent();
  }, [navigate, id]);

  const handleDelete = async () => {
    if (!student) return;

    const confirmDelete = window.confirm(
      `Are you sure you want to delete ${student.studentName}?`
    );

    if (!confirmDelete) return;

    const response = await deleteStudent(student.id);

    if (response.ok) {
      navigate("/admin-dashboard");
    } else {
      alert("Failed to delete student.");
    }
  };

  return (
    <Layout>
      <div className="max-w-7xl mx-auto px-6 py-4">
        <h1 className="text-3xl font-bold">Student Profile</h1>

        {loading && <p className="mt-4 text-gray-600">Loading...</p>}

        {!loading && student && (
          <div className="mt-6 bg-white shadow p-6 rounded-lg">
            <div className="flex items-center justify-between">
              <div>
                <h2 className="text-2xl font-bold">
                  Name: {student.studentName}
                </h2>
                <p className="text-gray-600">
                  Student Number: {student.studentNumber}
                </p>
              </div>

              <button
                className="bg-red-500 hover:bg-red-700 text-white font-bold py-2 px-4 rounded"
                onClick={handleDelete}
              >
                Delete Student
              </button>
            </div>
          </div>
        )}
      </div>
    </Layout>
  );
}

export default AdminStudentProfile;
